using Robust.Shared.Prototypes;

namespace Content.Shared._WF.ClothingLayer;

/// <summary>
/// Clothing sprites sorted by what their art covers, generated by <c>Tools/_WF/ClothingLayer/shapes.py</c>.
/// Paths are RSI paths under <c>/Textures</c>, as clothing prototypes give them.
/// </summary>
[Prototype("wfClothingShapes")]
public sealed partial class ClothingShapesPrototype : IPrototype
{
    [IdDataField]
    public string ID { get; private set; } = default!;

    /// <summary>
    /// Uniforms with fabric hanging at shoe height off the legs: skirts, gowns, robes, baggy trousers.
    /// </summary>
    [DataField]
    public HashSet<string> Drapes = new();

    /// <summary>
    /// Outer suits that cover the whole body from every side: hardsuits, EVA, bomb and fire suits.
    /// </summary>
    [DataField]
    public HashSet<string> Encloses = new();
}
